import { test } from "node:test";
import assert from "node:assert/strict";
import { createCartStore, createCatalog } from "../src/cart/store.js";
import { makeRouter } from "../src/cart/router.js";

function setup() {
  const store = createCartStore();
  const catalog = createCatalog({ milk: 150, bread: 250, rice: 1200 });
  const route = makeRouter(store, catalog);
  const put = (cartId, sku, body) =>
    route({ method: "PUT", path: `/carts/${cartId}/lines/${sku}`, rawBody: JSON.stringify(body) });
  return { route, put };
}

test("PUT on a new line creates it: 201 with a Location header", () => {
  const { put } = setup();
  const res = put("c1", "milk", { qty: 2 });
  assert.equal(res.status, 201);
  assert.equal(res.headers.Location, "/carts/c1/lines/milk");
  assert.deepEqual(res.body.lines, [{ sku: "milk", qty: 2, unitCents: 150, lineCents: 300 }]);
});

test("repeating the same PUT leaves the cart unchanged", () => {
  const { put, route } = setup();
  put("c1", "milk", { qty: 2 });
  const again = put("c1", "milk", { qty: 2 });
  const cart = route({ method: "GET", path: "/carts/c1" });
  console.log("after PUT milk=2 twice:", JSON.stringify(cart.body.lines));
  assert.equal(again.status, 200);
  assert.equal(cart.body.lines[0].qty, 2, "a retried PUT must not change the quantity");
});

test("PUT with a different quantity replaces the old one", () => {
  const { put } = setup();
  put("c1", "bread", { qty: 3 });
  const res = put("c1", "bread", { qty: 1 });
  assert.equal(res.status, 200);
  assert.equal(res.body.lines[0].qty, 1);
  assert.equal(res.body.subtotalCents, 250);
});

test("totals add delivery below the free-delivery threshold", () => {
  const { put } = setup();
  put("c1", "milk", { qty: 2 });
  const res = put("c1", "bread", { qty: 1 });
  assert.equal(res.body.subtotalCents, 550);
  assert.equal(res.body.deliveryCents, 399);
  assert.equal(res.body.totalCents, 949);
  const big = put("c1", "rice", { qty: 4 });
  assert.equal(big.body.deliveryCents, 0);
});

test("PUT validates sku and quantity", () => {
  const { put } = setup();
  assert.equal(put("c1", "unicorn", { qty: 1 }).status, 404);
  assert.equal(put("c1", "milk", { qty: 0 }).status, 422);
  assert.equal(put("c1", "milk", { qty: 1.5 }).status, 422);
  assert.equal(put("c1", "milk", {}).status, 422);
  assert.equal(put("c1", "milk", { qty: 100 }).status, 422);
});

test("DELETE removes a line and is repeatable", () => {
  const { put, route } = setup();
  put("c1", "milk", { qty: 2 });
  const del = () => route({ method: "DELETE", path: "/carts/c1/lines/milk" });
  assert.equal(del().status, 204);
  assert.equal(del().status, 204);
  assert.deepEqual(route({ method: "GET", path: "/carts/c1" }).body.lines, []);
});

test("unsupported methods get 405 with an Allow header; unknown carts 404", () => {
  const { route } = setup();
  const res = route({ method: "POST", path: "/carts/c1/lines/milk", rawBody: "{}" });
  assert.equal(res.status, 405);
  assert.equal(res.headers.Allow, "PUT, DELETE");
  assert.equal(route({ method: "GET", path: "/carts/missing" }).status, 404);
});
